impl crate::pure_semantics::children::ScopedChildren<NativeLeafSink> for NativeChildren<'_, '_> {
    fn visit_bound(
        &mut self,
        source: &Expr,
        source_key: &str,
        ty: &Type,
        binding: &syn::Ident,
        _: &mut NativeLeafSink,
    ) -> Result<Typed<syn::Expr>, RenderError> {
        // Reborrow inherited entries into this shorter body scope. Only binding
        // symbols are cloned, matching the old map overlay; no Type is cloned.
        let mut scope: HashMap<&str, (&Type, syn::Ident)> = self.bindings.clone();
        scope.insert(source_key, (ty, binding.clone()));
        let (output, ty) = crate::expression_with_calls(source, &scope, self.declarations)?;
        Ok(Typed { output, ty })
    }
}

/// One lexical body visit with a borrowed annotation and consumer-owned symbol.
/// Implementations overlay the original source key and restore outer scope;
/// they do not validate the name/type or mutate the caller's bindings.
pub(crate) trait ScopedChildren<S: super::sink::AggregateSink>: Children<S> {
    fn visit_bound(
        &mut self,
        source: &Expr,
        source_key: &str,
        ty: &crate::ir::Type,
        binding: &S::Binding,
        sink: &mut S,
    ) -> Result<Typed<S::Value>, RenderError>;
}

/// Aggregate syntax and lexical symbols consume checked facts only.
pub(crate) trait AggregateSink: LeafSink {
    fn binding(&mut self, name: &CheckedName) -> Self::Binding;
    fn aggregate(
        &mut self,
        checked: super::aggregate::CheckedAggregate<
            Self::Value,
            Self::Binding,
            <Self::Carriers as CarrierSink>::Value,
        >,
    ) -> Self::Value;
}

pub(crate) fn retained_value(value: syn::Expr, ty: &Type) -> syn::Expr {
    use crate::pure_semantics::ownership::Ownership;
    let ownership = if copy_type(ty) {
        Ownership::Copy
    } else {
        Ownership::Owned
    };
    retained_value_with_ownership(value, ownership)
}

/// Output-only retention; the semantic owner has already chosen ownership.
pub(crate) fn retained_value_with_ownership(
    value: syn::Expr,
    ownership: crate::pure_semantics::ownership::Ownership,
) -> syn::Expr {
    match ownership {
        crate::pure_semantics::ownership::Ownership::Copy => value,
        crate::pure_semantics::ownership::Ownership::Owned => syn::parse_quote!((#value).clone()),
    }
}

